import org.jsoup.Connection;
import org.junit.Test;
import org.junit.rules.ExpectedException;
import org.junit.Rule;

import java.io.UnsupportedEncodingException;
import java.net.MalformedURLException;
import java.net.URL;

import static org.junit.Assert.assertEquals;

public class UrlBuilderTest {

    @Rule
    public ExpectedException thrown = ExpectedException.none();

    @Test
    public void UrlBuilderValidURLTest() throws MalformedURLException{
        URL inputUrl = new URL("http://example.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);

        assertEquals(inputUrl, urlBuilder.build());
    }

    @Test
    public void UrlBuilderInvalidURLTest() {
        thrown.expect(MalformedURLException.class);
        URL inputUrl = new URL("htp://invalid.url.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);

        assertEquals(inputUrl, urlBuilder.build());
    }

    @Test
    public void AppendKeyValValidKeyValTest() throws UnsupportedEncodingException{
        URL inputUrl = new URL("http://example.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        Connection.KeyVal kv = Connection.KeyVal.create("key", "value");

        urlBuilder.appendKeyVal(kv);

        assertEquals("http://example.com?key=value", urlBuilder.build());
    }

    @Test
    public void AppendKeyValInvalidKeyValTest() throws UnsupportedEncodingException{
        URL inputUrl = new URL("http://example.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        Connection.KeyVal kv = Connection.KeyVal.create("invalid key", "invalid value");

        urlBuilder.appendKeyVal(kv);

        assertEquals("http://example.com?invalid%20key=invalid%20value", urlBuilder.build());
    }

}
